	return &labelClient{
		querier:       querier,
		dialect:       sql.NewSQLiteDialect(),
		table:         sql.Table{Schema: "", Name: "labels"},
		batchSize:     200,
		queryLimit:    1000,
		pageSize:      100,
		cursorKeys:    []string{"id"},
		strictUpdates: true,
		mutationHooks: mutationHooks,
		queryHooks:    queryHooks,
		panicHandler:  panicHandler,
	}
