// insertAndResolveID performs the INSERT and resolves the generated primary key.
func (c *legacyWidgetClient) insertAndResolveID(ctx context.Context, conn database.Querier, columns []string, args []any) (int64, error) {
	query, queryArgs := sql.BuildInsert(c.dialect, c.table, sql.InsertOptions{
		Columns:          columns,
		Values:           args,
		ReturningColumns: []string{"id"},
	})
	var id int64
	if err := conn.QueryRow(ctx, query, queryArgs...).Scan(&id); err != nil {
		return 0, err
	}
	return id, nil
}

// multiInsertAndResolveIDs performs a multi-row INSERT and resolves all generated primary keys.
func (c *legacyWidgetClient) multiInsertAndResolveIDs(ctx context.Context, conn database.Querier, columns []string, valueRows [][]any) ([]int64, error) {
	query, args := sql.BuildMultiInsert(c.dialect, c.table, sql.MultiInsertOptions{
		Columns:          columns,
		ValueRows:        valueRows,
		ReturningColumns: []string{"id"},
	})

	rows, err := conn.Query(ctx, query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var ids []int64
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, fmt.Errorf("scan legacy_widget id: %w", err)
		}
		ids = append(ids, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return ids, nil
}

