// Paginate returns a page of order_items with total count for offset-based pagination.
// A nil filter paginates all order_items.
func (c *orderItemClient) Paginate(ctx context.Context, input PaginateInput[OrderItemFilter], opts ...func(*CallOptions[OrderItemFieldOptions])) (*PaginateResult[OrderItem], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		return nil, fmt.Errorf("paginate order_items: LockMode is unsupported on sqlite dialect")
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpPaginate, Table: TableOrderItems, Schema: "",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[OrderItemFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Total count (delegates to Count — both are always generated)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, err
		}

		// Page data via GetMany (handles FieldOptions and relationships)
		orderItems, err := c.GetMany(ctx, &GetOrderItemsInput{
			Filter: input.Filter,
			Sorts:  input.Sort,
			Limit:  &input.Limit,
			Offset: &input.Offset,
		}, internalOpts)
		if err != nil {
			return nil, err
		}

		return &PaginateResult[OrderItem]{
			Items:      orderItems,
			TotalCount: totalCount,
			Offset:     input.Offset,
			Limit:      input.Limit,
			HasMore:    input.Limit > 0 && int64(input.Offset+input.Limit) < totalCount,
		}, nil
	})
	if err != nil {
		return nil, fmt.Errorf("paginate order_items: %w", err)
	}
	return result.(*PaginateResult[OrderItem]), nil
}

// Connection returns a Relay-style cursor-paginated connection of order_items.
// Sort order is determined by cursor_keys — custom sorts are not supported.
// Use Paginate for custom sort orders.
func (c *orderItemClient) Connection(ctx context.Context, input ConnectionInput[OrderItemFilter], opts ...func(*CallOptions[OrderItemFieldOptions])) (*Connection[OrderItem], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		return nil, fmt.Errorf("connection order_items: LockMode is unsupported on sqlite dialect")
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpConnection, Table: TableOrderItems, Schema: "",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[OrderItemFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Validate: first and last are mutually exclusive
		if input.First != nil && input.Last != nil {
			return nil, ErrInvalidCursor
		}

		// Total count (separate COUNT query — no cursor conditions)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, err
		}

		// Decode cursors and build keyset conditions
		var keysetConds []sql.Condition
		if input.After != nil {
			cursor, err := decodeOrderItemCursor(*input.After, c.cursorKeys)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, ">"))
		}
		if input.Before != nil {
			cursor, err := decodeOrderItemCursor(*input.Before, c.cursorKeys)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, "<"))
		}

		// Direction and limit
		limit := c.pageSize
		ascending := true
		if input.First != nil {
			limit = *input.First
		} else if input.Last != nil {
			limit = *input.Last
			ascending = false
		}

		// Fetch limit+1 rows via GetMany (handles FieldOptions, O2O joins, relationships, soft delete)
		connLimit := limit + 1
		orderItems, err := c.GetMany(ctx, &GetOrderItemsInput{
			Filter:     input.Filter,
			Sorts:      cursorSorts(c.cursorKeys, ascending),
			Limit:      &connLimit,
			conditions: keysetConds,
			// Each edge's cursor is encoded from the row it wraps, so the cursor
			// keys have to survive a narrowed FieldOptions — otherwise the
			// encoder reads fields the SELECT never filled and every cursor
			// carries zero values.
			requiredColumns: c.cursorKeys,
		}, internalOpts)
		if err != nil {
			return nil, err
		}

		// Trim extra row and determine page boundaries
		hasMore := len(orderItems) > limit
		if hasMore {
			orderItems = orderItems[:limit]
		}

		// Backward pagination: reverse for ascending cursor order
		if !ascending {
			slices.Reverse(orderItems)
		}

		// Build edges with encoded cursors
		edges := make([]Edge[OrderItem], len(orderItems))
		for i, row := range orderItems {
			cursor, err := encodeOrderItemCursor(c.cursorKeys, row)
			if err != nil {
				return nil, err
			}
			edges[i] = Edge[OrderItem]{
				Node:   row,
				Cursor: cursor,
			}
		}

		pageInfo := PageInfo{
			HasNextPage:     (ascending && hasMore) || (!ascending && input.Before != nil),
			HasPreviousPage: (!ascending && hasMore) || (ascending && input.After != nil),
		}
		if len(edges) > 0 {
			pageInfo.StartCursor = &edges[0].Cursor
			pageInfo.EndCursor = &edges[len(edges)-1].Cursor
		}

		return &Connection[OrderItem]{Edges: edges, PageInfo: pageInfo, TotalCount: totalCount}, nil
	})
	if err != nil {
		return nil, fmt.Errorf("connection order_items: %w", err)
	}
	return result.(*Connection[OrderItem]), nil
}

// encodeOrderItemCursor encodes cursor key values as a base64 JSON string.
func encodeOrderItemCursor(keys []string, o *OrderItem) (string, error) {
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "workspace_id":
			out["workspace_id"] = o.WorkspaceID
		case "order_id":
			out["order_id"] = o.OrderID
		case "product_id":
			out["product_id"] = o.ProductID
		case "quantity":
			out["quantity"] = o.Quantity
		case "unit_price":
			out["unit_price"] = o.UnitPrice
		}
	}
	data, err := json.Marshal(out)
	if err != nil {
		return "", fmt.Errorf("encode order_item cursor: %w", err)
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

// decodeOrderItemCursor decodes a cursor string into its key values,
// each unmarshaled into the key column's Go type.
func decodeOrderItemCursor(encoded string, keys []string) (map[string]any, error) {
	raw, err := decodeCursor(encoded, keys)
	if err != nil {
		return nil, err
	}
	var row OrderItem
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "workspace_id":
			err = json.Unmarshal(raw[key], &row.WorkspaceID)
			out[key] = row.WorkspaceID
		case "order_id":
			err = json.Unmarshal(raw[key], &row.OrderID)
			out[key] = row.OrderID
		case "product_id":
			err = json.Unmarshal(raw[key], &row.ProductID)
			out[key] = row.ProductID
		}
		if err != nil {
			return nil, err
		}
		if cursorValueIsNull(out[key]) {
			return nil, ErrInvalidCursor
		}
	}
	return out, nil
}

