// scanUsersWithOneToOneJoins scans rows from a LEFT JOIN query into
// User entities with O2O relationships populated.
// Routes columns by alias prefix and detects LEFT JOIN misses via NULL PK detection.
func scanUsersWithOneToOneJoins(rows database.Rows, columns []string) ([]*User, error) {
	var result []*User
	for rows.Next() {
		u := &User{}
		p := &UserProfile{}
		pHasData := false
		p2 := &UserProfile{}
		p2HasData := false
		p3 := &UserProfile{}
		p3HasData := false
		u2 := &User{}
		u2HasData := false
		u3 := &User{}
		u3HasData := false
		u4 := &User{}
		u4HasData := false

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "u.id":
				targets[idx] = &u.ID
			case "u.workspace_id":
				targets[idx] = &u.WorkspaceID
			case "u.email":
				targets[idx] = &u.Email
			case "p.id":
				targets[idx] = database.NullScan(&p.ID)
				pHasData = true
			case "p.user_id":
				targets[idx] = database.NullScan(&p.UserID)
			case "p.workspace_id":
				targets[idx] = database.NullScan(&p.WorkspaceID)
			case "p.bio":
				targets[idx] = &p.Bio
			case "p2.id":
				targets[idx] = database.NullScan(&p2.ID)
				p2HasData = true
			case "p2.user_id":
				targets[idx] = database.NullScan(&p2.UserID)
			case "p2.workspace_id":
				targets[idx] = database.NullScan(&p2.WorkspaceID)
			case "p2.bio":
				targets[idx] = &p2.Bio
			case "p3.id":
				targets[idx] = database.NullScan(&p3.ID)
				p3HasData = true
			case "p3.user_id":
				targets[idx] = database.NullScan(&p3.UserID)
			case "p3.workspace_id":
				targets[idx] = database.NullScan(&p3.WorkspaceID)
			case "p3.bio":
				targets[idx] = &p3.Bio
			case "u2.id":
				targets[idx] = database.NullScan(&u2.ID)
				u2HasData = true
			case "u2.workspace_id":
				targets[idx] = database.NullScan(&u2.WorkspaceID)
			case "u2.email":
				targets[idx] = database.NullScan(&u2.Email)
			case "u3.id":
				targets[idx] = database.NullScan(&u3.ID)
				u3HasData = true
			case "u3.workspace_id":
				targets[idx] = database.NullScan(&u3.WorkspaceID)
			case "u3.email":
				targets[idx] = database.NullScan(&u3.Email)
			case "u4.id":
				targets[idx] = database.NullScan(&u4.ID)
				u4HasData = true
			case "u4.workspace_id":
				targets[idx] = database.NullScan(&u4.WorkspaceID)
			case "u4.email":
				targets[idx] = database.NullScan(&u4.Email)
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan user with joins: %w", err)
		}

		// NULL detection — assign deepest chain first, then parents
		if u4HasData && u4.ID != 0 {
			p3.Users = u4
		} else {
			p3.Users = nil
		}
		if u3HasData && u3.ID != 0 {
			p2.Users = u3
		} else {
			p2.Users = nil
		}
		if u2HasData && u2.ID != 0 {
			p.Users = u2
		} else {
			p.Users = nil
		}
		if p3HasData && p3.ID != 0 {
			u3.Profile = p3
		} else {
			u3.Profile = nil
		}
		if p2HasData && p2.ID != 0 {
			u2.Profile = p2
		} else {
			u2.Profile = nil
		}
		if pHasData && p.ID != 0 {
			u.Profile = p
		} else {
			u.Profile = nil
		}

		result = append(result, u)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate user rows: %w", err)
	}
	return result, nil
}

